from abc import ABC, abstractmethod
from collections.abc import Iterable, Mapping
from types import MappingProxyType

from .core import (
    BOARD,
    PIECES,
    PIECES_BY_ID,
    SCHEMA_VERSION,
    Challenge,
    HexCoordinate,
    Orientation,
    Piece,
    Placement,
)


class IllegalMove(ValueError):
    def __init__(self, code: str, message: str, cells: Iterable[HexCoordinate] = ()) -> None:
        super().__init__(message)
        self.code = code
        self.cells = tuple(sorted(cells))


class Simulation:
    """Participant workspace and automatic recorder. Only successful actions mutate state."""

    def __init__(self, challenge: Challenge) -> None:
        self.challenge = challenge
        self.board = BOARD
        self.pieces = PIECES
        self.date = challenge.date
        self.exposed = BOARD.exposed(self.date)
        self._placements: dict[str, Placement] = {}
        self._actions: list[dict] = []

    @property
    def placements(self) -> Mapping[str, Placement]:
        return MappingProxyType(self._placements)

    @property
    def occupied(self) -> frozenset[HexCoordinate]:
        return frozenset(c for p in self._placements.values() for c in p.cells)

    @property
    def is_solved(self) -> bool:
        return (
            len(self._placements) == len(PIECES)
            and self.occupied == BOARD.coordinates - self.exposed
        )

    def orientations(self, piece_id: str) -> tuple[Orientation, ...]:
        return self._piece(piece_id).orientations()

    @staticmethod
    def _piece(piece_id: str) -> Piece:
        if not isinstance(piece_id, str) or piece_id not in PIECES_BY_ID:
            raise IllegalMove("unknown_piece", "Use one of the supplied P01–P12 piece IDs")
        return PIECES_BY_ID[piece_id]

    def _candidate(
        self, piece_id: str, origin: HexCoordinate, rotation: int, flipped: bool
    ) -> Placement:
        piece = self._piece(piece_id)
        if piece_id in self._placements:
            raise IllegalMove("piece_already_placed", f"Remove {piece_id} before placing it again")
        if not isinstance(origin, HexCoordinate):
            raise IllegalMove("invalid_origin", "Origin must be HexCoordinate(q, r)")
        try:
            shape = piece.transformed(rotation, flipped)
        except ValueError as error:
            raise IllegalMove("invalid_orientation", str(error)) from error
        cells = frozenset(c + origin for c in shape)
        for code, bad, message in (
            ("outside_board", cells - BOARD.coordinates, "Piece leaves the board"),
            ("exposed_cell", cells & self.exposed, "Piece covers an exposed calendar cell"),
            ("overlap", cells & self.occupied, "Piece overlaps an already placed piece"),
        ):
            if bad:
                raise IllegalMove(code, message, bad)
        return Placement(piece_id, origin, rotation, flipped, cells)

    def can_place(
        self, piece_id: str, origin: HexCoordinate, rotation: int = 0, flipped: bool = False
    ) -> bool:
        try:
            self._candidate(piece_id, origin, rotation, flipped)
            return True
        except IllegalMove:
            return False

    def place(
        self, piece_id: str, origin: HexCoordinate, rotation: int = 0, flipped: bool = False
    ) -> Placement:
        placement = self._candidate(piece_id, origin, rotation, flipped)
        self._placements[piece_id] = placement
        self._actions.append(
            {
                "action": "place",
                "piece_id": piece_id,
                "origin": origin.to_dict(),
                "rotation": rotation,
                "flipped": flipped,
            }
        )
        return placement

    def remove(self, piece_id: str) -> Placement:
        self._piece(piece_id)
        if piece_id not in self._placements:
            raise IllegalMove("piece_not_placed", f"{piece_id} is not on the board")
        placement = self._placements.pop(piece_id)
        self._actions.append({"action": "remove", "piece_id": piece_id})
        return placement

    def to_trace(self) -> dict:
        import copy

        return {
            "schema_version": SCHEMA_VERSION,
            "puzzle_version": self.challenge.puzzle_version,
            "challenge_id": self.challenge.id,
            "date": self.date.isoformat(),
            "actions": copy.deepcopy(self._actions),
        }


class PuzzleAlgorithm(ABC):
    @abstractmethod
    def solve(self, simulation: Simulation) -> None:
        """Implement your algorithm using simulation.place and simulation.remove."""
